mapper.select:
SELECT u.user_id AS userId, u.user_name AS userName, u.nick_name AS nickName, u.dept_id AS deptId, u.position_id AS positionId, u.user_status AS userStatus, p.position_name AS positionName FROM sys_user u LEFT JOIN position p ON p.id = u.position_id JOIN dept_position dp ON dp.position_id = u.position_id AND dp.status = 1 WHERE u.del_flag = '0' AND u.status = '0' AND u.user_status IN ('PRE_TRAINEE', 'FORMAL_TRAINEE', 'PENDING_PROMOTE') AND EXISTS (SELECT 1 FROM sys_user_role ur JOIN sys_role r ON r.role_id = ur.role_id WHERE ur.user_id = u.user_id AND r.role_key IN ('PRE_TRAINEE', 'FORMAL_TRAINEE'))
AND u.dept_id = #{deptId}
ORDER BY u.position_id, u.user_id
